DROP TABLE IF EXISTS `slaughter_inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `slaughter_inspection` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pig_id` bigint NOT NULL,
  `inspect_no` varchar(32) NOT NULL,
  `batch_no` varchar(32) NOT NULL,
  `ear_tag_no` varchar(32) DEFAULT NULL,
  `inspect_type` tinyint NOT NULL,
  `inspect_time` datetime NOT NULL,
  `temperature` decimal(4,1) DEFAULT NULL,
  `organ_check` text,
  `result` tinyint DEFAULT NULL,
  `status` tinyint DEFAULT '0',
  `conclusion` varchar(512) DEFAULT NULL,
  `issue_desc` varchar(512) DEFAULT NULL,
  `disposal` varchar(128) DEFAULT NULL,
  `veterinary` varchar(32) NOT NULL,
  `license_no` varchar(32) DEFAULT NULL,
  `e_signature` text,
  `file_ids` text,
  `content_hash` char(64) DEFAULT NULL,
  `source` varchar(16) DEFAULT 'MANUAL' COMMENT '数据来源 MANUAL/DEVICE/API/IMPORT',
  `source_ref` varchar(64) DEFAULT NULL COMMENT '来源设备号/单据号',
  `raw_payload` json DEFAULT NULL COMMENT '设备原始报文',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `void_flag` tinyint NOT NULL DEFAULT '0' COMMENT '0=有效 1=已作废',
  `void_reason` varchar(500) DEFAULT NULL COMMENT '作废理由（必填）',
  `void_operator` varchar(128) DEFAULT NULL COMMENT '作废操作人（实名）',
  `void_time` datetime DEFAULT NULL COMMENT '作废时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inspect_no` (`inspect_no`),
  KEY `idx_pig_type` (`pig_id`,`inspect_type`),
  KEY `idx_batch` (`batch_no`),
  KEY `idx_status_time` (`status`,`inspect_time`),
  KEY `idx_void_flag` (`void_flag`)
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='å± å®°æ£€éªŒ';
/*!40101 SET character_set_client = @saved_cs_client */;

