--
-- Table structure for table `carcass_batch`
--

DROP TABLE IF EXISTS `carcass_batch`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `carcass_batch` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `batch_no` varchar(32) NOT NULL,
  `pig_ids` json NOT NULL,
  `pig_count` int NOT NULL DEFAULT '0' COMMENT '批次头数（与 pig_ids 同步维护，用于归集上限判断，免去每次读 JSON 长度）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '归集状态：1=归集中（当日同场后续白条会并入）2=已封（不再并入，达到头数上限自动封或人工封批）',
  `total_weight_kg` decimal(8,1) DEFAULT NULL,
  `slaughterhouse` varchar(128) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `operator` varchar(32) DEFAULT NULL,
  `source` varchar(16) DEFAULT 'MANUAL' COMMENT '数据来源 MANUAL=人工建批/DEVICE=分拣台自动归集',
  `source_ref` varchar(64) DEFAULT NULL COMMENT '来源设备号（分拣台自动归集记设备编号，如 BATCH-001）',
  `raw_payload` json DEFAULT NULL COMMENT '设备原始报文（分拣台上报的完整报文，供逐字段核对）',
  `note` varchar(500) DEFAULT NULL,
  `void_flag` tinyint NOT NULL DEFAULT '0' COMMENT '0=有效 1=已作废',
  `void_reason` varchar(500) DEFAULT NULL COMMENT '作废理由（必填）',
  `void_operator` varchar(128) DEFAULT NULL COMMENT '作废操作人（实名）',
  `void_time` datetime DEFAULT NULL COMMENT '作废时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_no` (`batch_no`),
  KEY `idx_void_flag` (`void_flag`),
  KEY `idx_open_agg` (`slaughterhouse`,`source`,`status`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='èƒ´ä½“æ‰¹æ¬¡';
